    factors = set()
    r = x
    for p in small_primes:
        if p*p > r:
            break
        if r % p == 0:
            factors.add(p)
            while r % p == 0:
                r //= p
    if r > 1:
        if r < SIEVE_BOUND*SIEVE_BOUND:
            factors.add(r)
        else:
            factors.update(factorint(r).keys())
    return factors

