import sys, math, pickle, time
from sympy import primerange, factorint

SIEVE_BOUND = 20000
small_primes = list(primerange(2, SIEVE_BOUND))

def factorize(x):
    factors = set()
    r = x
    for p in small_primes:
        if p*p > r:
            break
        if r % p == 0:
            factors.add(p)
            while r % p == 0:
                r //= p
    if r > 1:
        if r < SIEVE_BOUND*SIEVE_BOUND:
            factors.add(r)
        else:
            factors.update(factorint(r).keys())
    return factors

def gen_sequence(a1, n_terms, verbose=False):
    a = [None, a1]
    rad = [None, factorize(a1)]
    prime_mask = {}
    for p in rad[1]:
        prime_mask[p] = (1 << 1)
    full_mask = (1 << 1)
    n = 1
    t0 = time.time()
    while n < n_terms:
        cand = a[n] + 1
        while True:
            f = factorize(cand)
            m = 0
            for p in f:
                m |= prime_mask.get(p, 0)
                if m == full_mask:
                    break
            if m == full_mask:
                break
            cand += 1
        a.append(cand)
        rad.append(f)
        n += 1
        full_mask |= (1 << n)
        for p in f:
            prime_mask[p] = prime_mask.get(p, 0) | (1 << n)
        if verbose and n % 500 == 0:
            print(f"  a1={a1}: n={n}, a_n={cand}, t={time.time()-t0:.1f}s", file=sys.stderr)
    return a, rad

if __name__ == "__main__":
    targets = [221, 247, 375, 4087, 4199]
    N = 3000
    data = {}
    for a1 in targets:
        print(f"=== a1={a1} ===", flush=True)
        a, rad = gen_sequence(a1, N, verbose=True)
        data[a1] = (a, rad)
        P1 = rad[1]
        print(f"P1=rad(a1)={sorted(P1)}, k={len(P1)}")
        print(f"a_{N} = {a[N]}")
    with open('/tmp/round-4/sim_data.pkl','wb') as f:
        pickle.dump(data, f)
    print("saved sim_data.pkl")

