import sys, json
from sympy import primefactors
from bisect import bisect_left

def radical_set(x, cache={}):
    if x in cache:
        return cache[x]
    r = frozenset(primefactors(x))
    cache[x] = r
    return r

def simulate(a1, N):
    a = [None, a1]
    R1 = radical_set(a1)
    M = [R1]
    for n in range(1, N):
        cur = a[n]
        x = cur + 1
        while True:
            Rx = radical_set(x)
            ok = True
            for S in M:
                if S.isdisjoint(Rx):
                    ok = False
                    break
            if ok:
                break
            x += 1
        a.append(x)
        Rx = radical_set(x)
        dominated_by_existing = any(S <= Rx for S in M)
        if not dominated_by_existing:
            M = [S for S in M if not (Rx < S)]
            M.append(Rx)
    return a, M

def check_period_for_L(a, N, L, tail=200):
    """Given candidate L, find T via binary search: a[n+T] = a[n]+L for a tail range of n."""
    arr = a[1:N+1]  # arr[0]=a1 ... arr[N-1]=a_N, 0-indexed for n=1..N
    Ts = []
    start_n = max(1, N - tail)
    for n in range(start_n, N):
        target = arr[n-1] + L  # a[n] is arr[n-1]
        idx = bisect_left(arr, target)
        if idx < len(arr) and arr[idx] == target:
            m = idx + 1  # 1-indexed
            Ts.append(m - n)
        else:
            Ts.append(None)
    # check all found and consistent
    valid = [t for t in Ts if t is not None]
    if len(valid) < tail * 0.9:
        return None, Ts.count(None)
    if len(set(valid)) == 1:
        return valid[0], 0
    else:
        return None, len(set(valid))

if __name__ == "__main__":
    a1 = int(sys.argv[1])
    N = int(sys.argv[2])
    L = int(sys.argv[3])
    a, M = simulate(a1, N)
    H_MRS = set()
    for S in M:
        H_MRS |= set(S)
    T, info = check_period_for_L(a, N, L)
    print(json.dumps({
        "a1": a1, "N": N, "L_tested": L, "T_found": T, "info": info,
        "H_MRS": sorted(H_MRS), "M_size": len(M)
    }))

