import json, sys
from itertools import combinations
from sympy import primefactors

def load(path):
    with open(path) as f:
        d = json.load(f)
    radicals = [frozenset(r) for r in d["radicals"]]
    return d["a1"], d["N"], d["terms"], radicals

def per_core_antichain(P1, radicals):
    """For every proper nonempty core S subsetneq P1, compute the set
    I_S (indices with imprint exactly S) and the final (n=N) minimal-radical
    antichain among {radicals[i] : i in I_S} (alive = undominated at N)."""
    P1 = frozenset(P1)
    all_subsets = []
    plist = sorted(P1)
    for r in range(1, len(plist)):
        for combo in combinations(plist, r):
            all_subsets.append(frozenset(combo))
    result = {}
    for S in all_subsets:
        I_S = [i for i, R in enumerate(radicals) if (R & P1) == S]
        # minimal antichain among radicals restricted to I_S
        antichain = []
        for i in I_S:
            R = radicals[i]
            # remove any existing chain member that is a superset of R
            dominated = [A for A in antichain if R <= A]
            if dominated:
                antichain = [A for A in antichain if not (R <= A)]
            if not any(A <= R for A in antichain):
                antichain.append(R)
        result[S] = {
            "I_S_size": len(I_S),
            "antichain": antichain,  # list of frozensets (each is S union Q)
        }
    return result

def summarize(a1, P1, radicals, N):
    res = per_core_antichain(P1, radicals)
    by_depth = {}
    for S, info in res.items():
        d = len(S)
        by_depth.setdefault(d, []).append((S, info))
    return res, by_depth

if __name__ == "__main__":
    path = sys.argv[1]
    a1, N, terms, radicals = load(path)
    P1 = frozenset(primefactors(a1))
    print(f"a1={a1}  P1={sorted(P1)}  N={N}")
    res, by_depth = summarize(a1, P1, radicals, N)
    for d in sorted(by_depth):
        print(f"-- depth {d} cores --")
        for S, info in by_depth[d]:
            Qs = [sorted(C - S) for C in info["antichain"]]
            print(f"  S={sorted(S)}  |I_S|={info['I_S_size']}  antichain(companions Q)={Qs}")

