    """rads: list, rads[0]=None, rads[1..N] = frozenset radicals.
    Returns fresh: list of bool, fresh[i] True iff no k<i has rads[k] proper-subset rads[i].
    Uses running antichain of minimal radicals among prefix."""
    N = len(rads) - 1
    fresh = [None] * (N + 1)
    antichain = set()
    for i in range(1, N + 1):
        r = rads[i]
        # i is fresh iff no element of current antichain (minimal radicals of prefix i-1) is a strict subset of r
        is_fresh = not any(C < r for C in antichain)
        fresh[i] = is_fresh
        # update antichain with r (insert if not dominated by existing; remove existing strict supersets of r)
        to_remove = [C for C in antichain if r < C]
        for C in to_remove:
            antichain.discard(C)
        if not any(C <= r and C != r for C in antichain):
            antichain.add(r)
    return fresh

def P1(rads):
    return rads[1]

def analyze_core(rads, fresh, S, N):
    """S: frozenset, proper nonempty subset of P1. Returns dict with:
    I_S indices (class S: rad(a_i) & P1 == S), J_S indices (rad(a_j) & S == empty),
    D_S (intersection over J_S of rad(a_j), minus P1),
    bundles: dict Q(frozenset, = rad(a_i)\\S for i in I_S) -> list of indices realizing it,
    fresh_bundles: subset of bundles where at least one realizing index is fresh (i.e. in V_S)
    """
    p1 = P1(rads)
    I_S = [i for i in range(1, N+1) if (rads[i] & p1) == S]
    J_S = [j for j in range(1, N+1) if (rads[j] & S) == frozenset()]
    if J_S:
        D_full = None
        for j in J_S:
            D_full = rads[j] if D_full is None else (D_full & rads[j])
        D_S = D_full - p1
    else:
        D_S = None
    bundles = {}
    for i in I_S:
        Q = rads[i] - S
        bundles.setdefault(Q, []).append(i)
