import sys, time, math
from sympy import primefactors

def radical_primes(x):
    return frozenset(primefactors(x))

def primorial(fs):
    p = 1
    for q in fs:
        p *= q
    return p

def simulate_track(a1, N):
    a = [None, a1]
    rad1 = radical_primes(a1)
    rads = [None, rad1]
    antichain = {rad1: primorial(rad1)}
    changes = []  # (n, 'add'/'remove', frozenset)
    n = 1
    while n < N:
        cand = a[n] + 1
        while True:
            ok = True
            for pr in antichain.values():
                if math.gcd(cand, pr) == 1:
                    ok = False
                    break
            if ok:
                break
            cand += 1
        n += 1
        a.append(cand)
        r = radical_primes(cand)
        rads.append(r)
        to_remove = [C for C in antichain if r < C]
        for C in to_remove:
            del antichain[C]
            changes.append((n, 'remove', C))
        dominated_new = any(C <= r and C != r for C in antichain)
        if not dominated_new and r not in antichain:
            antichain[r] = primorial(r)
            changes.append((n, 'add', r))
    return changes, antichain

if __name__ == "__main__":
    a1 = int(sys.argv[1])
    N = int(sys.argv[2])
    changes, final = simulate_track(a1, N)
    print(f"a_1={a1}, N={N}: total antichain-changing events = {len(changes)}")
    for n, kind, C in changes:
        print(f"  n={n:>8}  {kind:>6}  {sorted(C)}")
    print(f"final antichain (n={N}): {sorted(sorted(C) for C in final)}")

