    p1 = P1(rads)
    fresh = compute_freshness(rads)
    cores = proper_nonempty_subsets(p1)
    # precompute, for each core S, the set of ALL realized companion-sets (any occurrence, any index)
    all_bundles_any = {}  # S -> set of Q ever realized (any index)
    for S in cores:
        all_bundles_any[S] = set()
    for i in range(1, N + 1):
        r = rads[i]
        imprint = r & p1
        if imprint in all_bundles_any:
            all_bundles_any[imprint].add(r - imprint)

    # final antichain (literally alive at N): recompute via replay, tracking survivors
    antichain = {}
    for i in range(1, N + 1):
        r = rads[i]
        to_remove = [C for C in antichain if r < C]
        for C in to_remove:
            del antichain[C]
        if not any(C <= r and C != r for C in antichain) and r not in antichain:
            antichain[r] = True
    final_alive = set(antichain.keys())

    print(f"=== a_1={a1} ===")
    for S in cores:
        bundles_fresh = {}
        for i in range(1, N+1):
            r = rads[i]
            if (r & p1) == S and fresh[i]:
                Q = r - S
                bundles_fresh.setdefault(Q, i)
        D_full = None
        J_S_any = False
        for j in range(1, N+1):
            if (rads[j] & S) == frozenset():
                J_S_any = True
                D_full = rads[j] if D_full is None else (D_full & rads[j])
        D_S = (D_full - p1) if D_full is not None else frozenset()
        for Q, idx in bundles_fresh.items():
            if len(Q) < 3:
                continue
            if (Q & D_S) != frozenset():
                continue  # not even D_S-disjoint, skip
            # check subset avoidance: any proper nonempty subset of Q ever realized (any occurrence) for this S
            violations = []
            for r_ in range(1, len(Q)):
                for combo in combinations(sorted(Q), r_):
                    Qp = frozenset(combo)
                    if Qp in all_bundles_any[S]:
                        violations.append(sorted(Qp))
            alive = (S | Q) in final_alive
            status = "SUBSET-AVOIDANCE HOLDS" if not violations else f"VIOLATED by {violations}"
            print(f"  S={sorted(S)} Q={sorted(Q)} (size {len(Q)}) first_fresh_idx={idx} "
                  f"alive_at_N={alive}  {status}")

if __name__ == "__main__":
