"""Independent, from-scratch efficient generator for the IMO 2026 P6 sequence,
using a minimal-radical antichain for O(small) admissibility checks per
candidate integer (no need to check gcd against every previous term).

Admissibility fact used (elementary, re-derived independently here, not
copied from any builder script): a candidate x is admissible against the
whole prefix a_1..a_n iff rad(x) intersects rad(a_i) for every i<=n, iff
rad(x) intersects every element of the *minimal* radicals seen so far
(since if R1 subset R2 and rad(x) hits R1, it automatically hits R2).
So maintain the antichain of subset-minimal radicals; a candidate is
admissible iff, for every antichain radical R (a set of primes), x is
divisible by at least one prime in R.

Full factorization of x is only performed once x is ACCEPTED (needed to
know its exact radical for updating the antichain and for reporting).
"""
import sys
from sympy import factorint

def radical_primes(n):
    return set(factorint(n).keys())

def update_antichain(antichain, new_r):
    """antichain: list of frozensets (radicals), pairwise subset-incomparable.
    Insert new_r if it is not dominated (no existing R subset of new_r);
    remove any existing R that is a strict superset of new_r."""
    for R in antichain:
        if R <= new_r:   # R subset-or-equal of new_r -> new_r not minimal (or duplicate)
            return antichain  # no change; new_r already dominated (or equal, already present in spirit)
    # new_r is not dominated by anything currently in the antichain;
    # remove any existing members that are strict supersets of new_r
    antichain = [R for R in antichain if not (new_r < R)]
    antichain.append(new_r)
    return antichain

def admissible(x, antichain):
    for R in antichain:
        if not any(x % p == 0 for p in R):
            return False
    return True

def gen_fast(a1, N, report_every=None, track_antichain_history=False):
    seq = [a1]
    r1 = radical_primes(a1)
    antichain = [frozenset(r1)]
    history = []  # (n, frozenset(antichain)) snapshots if requested
    if track_antichain_history:
        history.append((1, frozenset(antichain)))
    x = a1 + 1
    while len(seq) < N:
        if admissible(x, antichain):
            seq.append(x)
            rx = frozenset(radical_primes(x))
            antichain = update_antichain(antichain, rx)
            if track_antichain_history:
                history.append((len(seq), frozenset(antichain)))
            if report_every and len(seq) % report_every == 0:
                print(f"  n={len(seq)} a_n={x}", file=sys.stderr)
            x += 1
        else:
            x += 1
    return seq, antichain, history

if __name__ == "__main__":
    a1 = int(sys.argv[1])
    N = int(sys.argv[2])
    seq, antichain, _ = gen_fast(a1, N)
    for i, v in enumerate(seq, 1):
        print(i, v)
    print("FINAL ANTICHAIN:", antichain, file=sys.stderr)

