import math, sys, time

def radical_subset(a, b):
    """True if rad(a) subseteq rad(b), using only gcd (no factoring)."""
    x = a
    while True:
        g = math.gcd(x, b)
        if g == 1:
            break
        x //= g
    return x == 1

def generate_with_watch(a1, N, watch_primes, P1, time_budget=None, report_every=None):
    """Generate a_1..a_N via greedy rule (antichain-accelerated admissibility,
    no factoring needed). Simultaneously, for each term, compute its 'core'
    S(n) = {p in P1 : p | a_n} and its watch-signature sig(n) = {p in watch_primes: p|a_n}
    (both via cheap mod tests, no factoring). Returns:
      seq: list of a_n values (index 0 = a_1)
      cores: list of frozenset core per index
      sigs: list of frozenset watch-signature per index
    """
    seq = [a1]
    antichain = [a1]
    t0 = time.time()
    watch_primes = sorted(watch_primes)
    P1 = sorted(P1)

    def core_of(x):
        return frozenset(p for p in P1 if x % p == 0)
    def sig_of(x):
        return frozenset(p for p in watch_primes if x % p == 0)

    cores = [core_of(a1)]
    sigs = [sig_of(a1)]

    n = 1
    hit_budget = False
    while n < N:
        x = seq[-1] + 1
        while True:
            ok = True
            for m in antichain:
                if math.gcd(x, m) == 1:
                    ok = False
                    break
            if ok:
                break
            x += 1
        seq.append(x)
        cores.append(core_of(x))
        sigs.append(sig_of(x))
        # update antichain
        dominated_by_existing = False
        new_antichain = []
        for m in antichain:
            if m != x and radical_subset(m, x):
                dominated_by_existing = True
                new_antichain.append(m)
            elif m != x and radical_subset(x, m):
                continue
            else:
                new_antichain.append(m)
        antichain = new_antichain
        if not dominated_by_existing:
            antichain.append(x)
        n += 1
        if report_every and n % report_every == 0:
            print(f"  n={n} a_n={seq[-1]} antichain_size={len(antichain)} elapsed={time.time()-t0:.1f}s", file=sys.stderr)
        if time_budget and time.time() - t0 > time_budget:
            print(f"  TIME BUDGET HIT at n={n}", file=sys.stderr)
            hit_budget = True
            break
    return seq, cores, sigs, hit_budget

if __name__ == "__main__":
    pass

