import numpy as np, time, sys

LIMIT = 150_000_000
spf = np.load('/tmp/round-11/spf150.npy')

def rad_set(x):
    primes = set()
    if x <= LIMIT:
        while x > 1:
            p = int(spf[x])
            primes.add(p)
            while x % p == 0:
                x //= p
    else:
        d = 2
        while d*d <= x:
            if x % d == 0:
                primes.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            primes.add(x)
    return frozenset(primes)

def hits_all(radx, antichain):
    for S in antichain:
        if radx.isdisjoint(S):
            return False
    return True

def add_to_antichain(antichain, R):
    new_list = []
    dominated = False
    for S in antichain:
        if S <= R:
            dominated = True
            new_list.append(S)
        elif R < S:
            continue
        else:
            new_list.append(S)
    if not dominated:
        new_list.append(R)
    return new_list

def gen_sequence(a1, n_terms, report_every=None):
    a = [a1]
    antichain = [rad_set(a1)]
    radicals = [rad_set(a1)]
    x = a1
    t0 = time.time()
    for n in range(1, n_terms):
        cand = x + 1
        while True:
            radc = rad_set(cand)
            if hits_all(radc, antichain):
                break
            cand += 1
        a.append(cand)
        R = rad_set(cand)
        radicals.append(R)
        antichain = add_to_antichain(antichain, R)
        x = cand
        if report_every and n % report_every == 0:
            print(f'  n={n} a_n={x} elapsed={time.time()-t0:.1f}s antichain_size={len(antichain)}', file=sys.stderr)
    return a, radicals

