def factor(m, primes):
    f = set()
    x = m
    for p in primes:
        if p*p > x:
            break
        while x % p == 0:
            f.add(p)
            x //= p
    if x > 1:
        f.add(x)
    return frozenset(f)

def run(a1, N, prime_limit=20000):
    primes = sieve_primes(prime_limit)
    P1 = factor(a1, primes)

    a = a1
    rad1 = factor(a1, primes)
    antichain = [rad1]

