import sys, time

def sieve_primes(limit):
    is_c = bytearray(limit+1)
    primes = []
    for i in range(2, limit+1):
        if not is_c[i]:
            primes.append(i)
            for j in range(i*i, limit+1, i):
                is_c[j] = 1
    return primes

def factor(m, primes):
    f = set()
    x = m
    for p in primes:
        if p*p > x:
            break
        while x % p == 0:
            f.add(p)
            x //= p
    if x > 1:
        f.add(x)
    return frozenset(f)

