import sys, time
import sympy

def run(a1, N, P1, target_cores, outfile):
    """Stream-generate the greedy sequence, track backbone for each core in target_cores
    (list of frozensets, e.g. [frozenset({67})]) without holding full history in memory."""
    rad1 = frozenset(sympy.primefactors(a1))
    antichain = [rad1]
    cur = a1
    backbone = {c: None for c in target_cores}
    shrink_events = {c: [] for c in target_cores}
    class_count = {c: 0 for c in target_cores}
    last_seen = {c: None for c in target_cores}
    core = rad1 & P1
    if core in backbone:
        comp = rad1 - P1
        backbone[core] = set(comp)
        class_count[core] = 1
        last_seen[core] = (1, comp)

    t0 = time.time()
    for n in range(2, N+1):
        c = cur + 1
        while True:
            ok = True
            for S in antichain:
                hit = False
                for p in S:
                    if c % p == 0:
                        hit = True
                        break
                if not hit:
                    ok = False
                    break
            if ok:
                break
            c += 1
        R = frozenset(sympy.primefactors(c))
        cur = c
        new_antichain = [S for S in antichain if not (R < S)]
        dominated = any(S <= R for S in new_antichain)
        if not dominated:
            new_antichain.append(R)
        antichain = new_antichain

        core = R & P1
        if core in backbone:
            comp = R - P1
            class_count[core] += 1
            last_seen[core] = (n, comp)
            if backbone[core] is None:
                backbone[core] = set(comp)
            else:
                newB = backbone[core] & comp
                if newB != backbone[core]:
                    shrink_events[core].append((n, dict(old=sorted(backbone[core]), comp=sorted(comp), new=sorted(newB))))
                    backbone[core] = newB
        if n % 1_000_000 == 0:
            print(f"  progress n={n} t={time.time()-t0:.1f}s cur_value~{cur}", file=sys.stderr, flush=True)

    with open(outfile, "w") as f:
        f.write(f"a1={a1} N={N} last_term={cur}\n")
        for c in target_cores:
            f.write(f"core={sorted(c)} count={class_count[c]} backbone={sorted(backbone[c]) if backbone[c] else None} last_seen={last_seen[c]}\n")
            f.write(f"  shrink_events ({len(shrink_events[c])}):\n")
            for ev in shrink_events[c]:
                f.write(f"    n={ev[0]} {ev[1]}\n")
    print("DONE", outfile, file=sys.stderr)

if __name__ == "__main__":
    a1 = int(sys.argv[1])
    N = int(sys.argv[2])
    P1 = frozenset(sympy.primefactors(a1))
    assert len(P1) == 2, f"expected |P1|=2, got {P1}"
    p, q = sorted(P1)
    target_cores = [frozenset({p}), frozenset({q})]
    outfile = f"/tmp/round-13/backbone_{a1}_{N}.txt"
    run(a1, N, P1, target_cores, outfile)

