import sys, math
from sympy import primerange, factorint

def sieve_spf(limit):
    spf = list(range(limit+1))
    for i in range(2, int(limit**0.5)+1):
        if spf[i]==i:
            for j in range(i*i, limit+1, i):
                if spf[j]==j:
                    spf[j]=i
    return spf

def radical(m, spf):
    s=set()
    while m>1:
        p=spf[m]
        s.add(p)
        while m%p==0:
            m//=p
    return frozenset(s)

def generate(a1, N, spf, limit):
    # antichain-based fast generator
    a=[a1]
    rad1 = radical(a1, spf)
    antichain=[rad1]
    cur=a1
    while len(a) < N:
        cand = cur+1
        while True:
            r = radical(cand, spf)
            if all(r & s for s in antichain):
                break
            cand += 1
        r = radical(cand, spf)
        a.append(cand)
        # update antichain: remove supersets of r (strict), add r if not dominated
        dominated = any(s <= r for s in antichain)  # existing s subset-or-eq of r => r dominated (already satisfied by s? actually need r doesn't need re-adding if some existing s subset of r since satisfying s implies satisfying r... wait antichain semantics: candidate admissible iff its radical intersects every antichain radical. dominance to prune: keep only minimal radicals under inclusion.
        if not dominated:
            antichain = [s for s in antichain if not (r < s)]
            antichain.append(r)
        cur = cand
    return a

